<?php
declare(strict_types=1);
require_once __DIR__ . '/access.php'; require_role('admin'); require_once __DIR__ . '/activity.php';
if ($_SERVER['REQUEST_METHOD'] === 'POST') { verify_csrf(); $id = (int) ($_POST['id'] ?? 0); $status = (string) ($_POST['status'] ?? ''); if (in_array($status, ['approved', 'rejected'], true)) { db()->prepare('UPDATE leave_requests SET status = ? WHERE id = ?')->execute([$status, $id]); } }
$requests = db()->query("SELECT lr.*, u.name FROM leave_requests lr INNER JOIN users u ON u.id = lr.employee_id ORDER BY lr.created_at DESC")->fetchAll();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Manage Leave</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4"><div class="d-flex justify-content-between"><h1 class="h3">Manage Leave</h1><a href="admin_dashboard.php">Dashboard</a></div><div class="card card-body"><table class="table"><thead><tr><th>Employee</th><th>Dates</th><th>Reason</th><th>Status</th><th></th></tr></thead><tbody><?php foreach ($requests as $request): ?><tr><td><?= e($request['name']) ?></td><td><?= e($request['from_date'] . ' to ' . $request['to_date']) ?></td><td><?= e($request['reason']) ?></td><td><?= e(ucfirst($request['status'])) ?></td><td><?php if ($request['status'] === 'pending'): ?><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int) $request['id'] ?>"><button class="btn btn-sm btn-success" name="status" value="approved">Approve</button> <button class="btn btn-sm btn-danger" name="status" value="rejected">Reject</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></main></body></html>
